/bin/bash -lc "PYTHONDONTWRITEBYTECODE=1 PYTHONPATH=src python3 -B - <<'PY'
from pathlib import Path
from zf.core.paths import state_path
from zf.cli import event_path
for configured in ['runtime-data', '/var/run/demo', 'nested/state', '../shared/state']:
    p = Path(configured)
    expected = (p if p.is_absolute() else Path('/srv/demo') / p).resolve()
    assert state_path(Path('/srv/demo'), configured) == expected
    assert event_path(Path('/srv/demo'), {'project': {'state_dir': configured}}) == expected / 'events.jsonl'
    print(f'{configured} -> {expected}; CLI PASS')
namespace = {}
exec(compile(Path('tests/test_paths.py').read_text(), 'tests/test_paths.py', 'exec'), namespace)
for name, fn in namespace.items():
    if name.startswith('test_'):
        try:
            fn()
            print(f'{name}: PASS')
        except AssertionError:
            print(f'{name}: FAIL')
print('/var/run is_symlink:', Path('/var/run').is_symlink())
print('/var/run resolves to:', Path('/var/run').resolve())
PY"

